# capture forms: struct foo *var = <expr with skb>;
CAPTURE_RE = re.compile(
    r'^(?P<indent>\s*)(?P<type>(?:const\s+)?struct\s+\w+|\w+)\s*\*\s*(?P<var>\w+)\s*=\s*(?P<expr>[^;]+);'
)

def func_spans(lines):
    # crude: find lines matching 'funcname(...)' at col 0 followed by '{' at col 0
    spans = []
    start = None
    fname = None
    for i, l in enumerate(lines):
        if re.match(r'^\w[\w\s\*,]*\)\s*$', l) or re.match(r'^\w[\w\s\*,]*$', l):
            pass
        if l.startswith('{') and start is None:
            start = i
            # find function name: look upward for the last line with '(' at depth 0
            for j in range(i-1, max(-1, i-12), -1):
                m = re.search(r'(\w+)\s*\(', lines[j])
                if m and not lines[j].lstrip().startswith(('*','/','#')) and '=' not in lines[j].split('(')[0]:
                    fname = m.group(1); break
        if l.startswith('}') and start is not None:
            spans.append((start, i, fname))
            start = None; fname = None
    return spans

