                if not m: continue
                expr = m.group('expr')
                if 'skb' not in expr and 'skb_' not in expr: continue
                if 'skb' in expr and ('skb->data' in expr or 'skb_header_pointer' in expr or '_hdr(skb)' in expr or 'skb_network_header' in expr or 'skb_transport_header' in expr or 'skb_mac_header' in expr):
                    captures.append((m.group('var'), i, expr.strip()))
            if not captures: continue
            # find pulls
            pulls = [i for i,l in enumerate(body) if PULL_RE.search(l)]
            if not pulls: continue
            for (var, ci, expr) in captures:
