import re, sys, os
root = "net"
pullre = re.compile(r'\b(pskb_may_pull|pskb_pull|pskb_pull_reserve|__pskb_pull_tail|skb_linearize|__skb_linearize)\s*\(')
capre = re.compile(r'^\s*(?:static\s+)?(?:const\s+)?(?:struct\s+\w+|u8|u16|u32|__be16|__be32|unsigned char|char|void|__wsum)\s*\*?(\w+)\s*=\s*(.*(?:skb_header_pointer\s*\(|skb->data|_hdr\(skb\)|skb_network_header|skb_transport_header|skb_mac_header).*)[;,]\s*$')
results = []
for dirpath, dirs, files in os.walk(root):
    for f in files:
        if not f.endswith('.c'): continue
        p = os.path.join(dirpath, f)
        try: lines = open(p, encoding='utf-8', errors='replace').read().splitlines()
        except: continue
        # function starts: heururistic - line starting at col 0 containing '(' and ending '{'
        fstarts = [i for i,l in enumerate(lines) if re.match(r'^[A-Za-z_].*\(.*$', l) and (l.rstrip().endswith('{') or (i+1 < len(lines) and lines[i+1].strip().startswith('{')))]
        # simpler: process whole file, track captures within +/- 60 lines of a pull
        pulls = [i for i,l in enumerate(lines) if pullre.search(l)]
        caps = []
        for i,l in enumerate(lines):
            m = capre.match(l)
            if m: caps.append((i, m.group(1), m.group(2)))
        for pi in pulls:
            # find enclosing function approximate: previous fstart
            fs = max([s for s in fstarts if s <= pi], default=0)
            fe = min([s for s in fstarts if s > pi], default=len(lines))
            for (ci, name, init) in caps:
                if fs <= ci <= fe and ci <= pi:
                    # look for uses after pull within function until next pull or end
                    usere = re.compile(r'\b' + re.escape(name) + r'\b\s*(->|\[|\)|\]|\.|\+|-|\)|;)')
                    for ui in range(pi+1, fe):
                        if pullre.search(lines[ui]): break
                        if usere.search(lines[ui]):
                            # check if re-assigned before use
                            reass = re.compile(r'\b' + re.escape(name) + r'\s*=')
                            blocked = False
                            for k in range(pi+1, ui):
                                if reass.search(lines[k]) and not re.search(r'==', lines[k]): blocked = True; break
                            if not blocked:
                                results.append((p, ci+1, pi+1, ui+1, name, init.strip()[:60], lines[ui].strip()[:70]))
                            break
for r in results:
    print("%s\tcap@%d %s = %s\t pull@%d\t use@%d: %s" % (r[0], r[1], r[4], r[5], r[2], r[3], r[6]))
EOF
